//! Runtime support for Rust code generated by `php2rust`.
//!
//! Generated code manipulates [`Value`]s, which reproduce PHP's dynamic value
//! semantics (type juggling, copy-on-write arrays, byte strings) in safe Rust.
//! All per-request state lives in a [`Context`]; there is no global mutable
//! state, so one request can never observe memory owned by another.

#![forbid(unsafe_code)]

mod array;
mod context;
mod error;
mod format;
mod numeric;
mod string;
mod value;

pub use array::{Key, PhpArray};
pub use context::Context;
pub use error::{PhpError, PhpResult};
pub use string::PhpString;
pub use value::Value;

/// Everything generated code needs, imported with `use php_rt::prelude::*;`.
pub mod prelude {
    pub use crate::{Context, Key, PhpArray, PhpError, PhpResult, PhpString, Value};
}

/// Runs a generated script as a CLI program: executes it, writes its output to
/// stdout, reports an uncaught error the way the PHP CLI does, and returns the
/// process exit code.
pub fn run_main(script: fn(&mut Context) -> PhpResult<Value>) -> i32 {
    use std::io::Write;

    let mut ctx = Context::new();
    let result = script(&mut ctx);
    let mut stdout = std::io::stdout().lock();
    let _ = stdout.write_all(&ctx.take_output());
    let _ = stdout.flush();
    match result {
        Ok(_) => 0,
        Err(PhpError::Exit(code)) => code,
        Err(err) => {
            eprintln!("PHP Fatal error:  Uncaught {err}");
            255
        }
    }
}
